window.RP_SESSION={"id":"S-81a29aad9ca9","messages":[{"id":"RP-II-0023106","time":"2026-01-12T15:14:00+09:00","room":"RP II","name":"에레모시스 / 아인츠하","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"불에 데인 듯한 고통이 눈가를 지나쳐간다. 새벽의 기로 시간의 지평사이로 사라지는 광기의 한숨에 잠시 시야를 두고 나면, 어느덧 시간이 훌쩍 지나가버린다. 검은 요정은 나지막한 어투로 그 날의 시간을 중얼거려 본다. 결국엔 말소리 마다 붉은 환상이 되어 사라질 테지만, 결국에는 그것도 ..후회와 망각의 기로로 사라져간다. \n\n지난 날을 후회해봤자 아무런 의미가 없다. 하지만, 계속하여 이어지는 기억의 속죄에 결국에는 꺼져가는 촛불 처럼 아려오는 마음의 편린을 거부 할 수가 없어서 인상을 찌푸렸다. 진자 운동 하는 시계바늘추와 ㅡ 이야기를 낼 듯 말 듯한, 죽어버린 시간이 함께하는 새의 박제가 눈에 들어왔다. 가만히 손가락을 움직여 진자운동을 멈추었다.\n\n이렇게 시간을 멈추면 좋으려만, 결국에는 시간이 멈추지 않는 구나. 시 적인 표현에 앞써 요정의 현실을 보자면, 그렇게 앞만 보고 가라는 말을 무색하게도 짙은 새벽녘의 안개 같이 거짓된 감정에 스며들어온다. '비어있음'을 인지 하지","characters":["P-d6e0d1eb8b63"]},{"id":"RP-II-0023107","time":"2026-01-12T15:15:00+09:00","room":"RP II","name":"에레모시스 / 아인츠하","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"@마리우스 @Maria Anaïs Ésther","characters":["P-d6e0d1eb8b63"]},{"id":"RP-II-0023108","time":"2026-01-12T15:16:00+09:00","room":"RP II","name":"에레모시스 / 아인츠하","profile":"FomalHaut","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d6e0d1eb8b63"]},{"id":"RP-II-0023109","time":"2026-01-12T15:16:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
